  for(let i=0;i<args.length;i+=2){const key=args[i],value=args[i+1];if(!allowed.has(key)||Object.hasOwn(options,key)||typeof value!=='string'||!value||value.startsWith('--'))throw new Error('INVALID_CLI_ARGUMENT');options[key]=value;}
  if(!options['--out'])throw new Error('OUTPUT_REQUIRED');if(mode==='diagnostic'&&!options['--probes'])throw new Error('PROBES_REQUIRED');return {mode,options:{...(options['--root']?{projectRoot:path.resolve(options['--root'])}:{}),outputDirectory:options['--out'],...(options['--probes']?{probes:options['--probes'].split(',').filter(Boolean)}:{}),...(options['--bridge-record']?{bridgeRecord:options['--bridge-record']}:{})}};
